#include <bits/stdc++.h>
using namespace std;
const int MAX=2000005;
int total,edge_next[MAX],head[MAX],dest[MAX],capacity[MAX],dist[MAX],start,end_point,n,m,xs[MAX],ys[MAX],visited[MAX],cost[MAX],flow[MAX],current[MAX],k_param,c_param,d_param;
queue<int> q;
void connect(int a,int b,int z,int v){
    edge_next[++total]=head[a];
    head[a]=total;
    dest[total]=b;
    capacity[total]=z;
    cost[total]=v;
    edge_next[++total]=head[b];
    head[b]=total;
    dest[total]=a;
    capacity[total]=0;
    cost[total]=-v;
}
int shortest_path(){
    q.push(start);
    memset(dist,0x3f,sizeof dist);
    dist[start]=0;
    while (!q.empty()){
        int current_node=q.front();q.pop();visited[current_node]=0;
        for (int i=head[current_node];i;i=edge_next[i])
            if (capacity[i]&&dist[dest[i]]>dist[current_node]+cost[i]){
                dist[dest[i]]=dist[current_node]+cost[i];
                if (!visited[dest[i]]){
                    visited[dest[i]]=1;
                    q.push(dest[i]);
                }
            }
    }
    return dist[end_point]<=1e9;
}
int augment(int node,int flow_in){
    int total_flow=0,flow_bottle;
    visited[node]=1;
    if (node==end_point)return flow_in;
    for (int &i=current[node];i;i=edge_next[i])
        if (!visited[dest[i]]&&capacity[i]&&dist[dest[i]]==dist[node]+cost[i]&&(flow_bottle=min(flow_in,augment(dest[i],min(flow_in,capacity[i]))))){
            capacity[i]-=flow_bottle;
            capacity[i^1]+=flow_bottle;
            total_flow+=flow_bottle;flow_in-=flow_bottle;
            if (!flow_in)return total_flow;
        }
    return total_flow;	
}
int main(){
    scanf("%d%d%d%d%d",&n,&m,&k_param,&c_param,&d_param);
    start=0; end_point=1;
    total=1;
    for (int i=1;i<=k_param;i++){
        int x;
        scanf("%d",&x);
        connect(start,x+1,1,0);
    }
    for (int i=1;i<=m;i++)scanf("%d%d",&xs[i],&ys[i]);
    for (int i=0;i<=n+k_param;i++){
        connect(2+i*n,end_point,k_param,0);
        if (i==n+k_param)break;
        for (int j=1;j<=m;j++)
            for (int l=k_param;l>=0;l--) {
                connect(xs[j]+1+i*n,ys[j]+1+i*n+n,1,(l*2+1)*d_param+c_param);
                connect(ys[j]+1+i*n,n+xs[j]+1+i*n,1,(l*2+1)*d_param+c_param);
            }
        for (int j=1;j<=n;j++)connect(j+1+i*n,j+1+i*n+n,k_param,c_param);
    }
    printf("%d\n",gao());
}
